INSERT INTO products (id, category_id, name_uz, name_ru, slug, description_uz, description_ru, price, old_price, discount_ends_at, weight_label, image_url, ingredients_uz, ingredients_ru, calories, shelf_life_hours, prep_time_minutes, is_available, is_popular, is_new, sort_order, unit_type, min_quantity, quantity_step, is_deleted, created_at, updated_at) VALUES
(101, 1, 'Mo‘jiza 777 Maxsus Torti', 'Фирменный торт «Mo‘jiza 777»', 'mojiza-777-maxsus-torti', 'Belgiya shokoladi, 82.5% sof sariyog'', o''rmon yong''og''i va tabiiy mevali sharbat bilan to''yintirilgan biskvitli eksklyuziv tort. Qandolat uyimizning ramzi va faxri!', 'Эксклюзивный фирменный торт: насыщенный шоколадный бисквит, бельгийский шоколад, натуральное масло 82.5%, лесной орех и нежнейший ганаш. Гордость дома Mo‘jiza 777!', 180000, 210000, '2026-11-08T18:58:44.785Z', '1.2 kg', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800&auto=format&fit=crop&q=80', 'Oliy navli un, Belgiya shokoladi, 82.5% tabiiy sariyog'', o''rmon yong''og''i, tabiiy qaymoq, kakao, vanil ekstrakti.', 'Мука высшего сорта, бельгийский шоколад, натуральное сливочное масло 82.5%, лесной фундук, свежие сливки, какао, экстракт мадагаскарской ванили.', 360, 72, 0, TRUE, TRUE, FALSE, 1, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(102, 1, 'Qizil Baxmal (Red Velvet)', 'Красный Бархат (Red Velvet)', 'qizil-baxmal', 'Mayin qizil baxmal biskvitlari va nozik qaymoqli krem-chiz qatlamlari. Yangi malina va qulupnay mevalari bilan bezatilgan shohona desert.', 'Бархатистый красный бисквит с легкой шоколадной ноткой и нежнейшим кремом на основе сливочного крем-чиза. Украшен спелыми ягодами малины и клубники.', 145000, NULL, NULL, '1.0 kg', 'https://images.unsplash.com/photo-1586788680434-30d324b2d46f?w=800&auto=format&fit=crop&q=80', 'Oliy navli un, tabiiy qaymoqli pishloq (krem-chiz), 82.5% sariyog'', qizil meva ekstrakti, qand lavlagi sharbati, tuxum.', 'Мука высшего сорта, сливочный сыр крем-чиз, сливочное масло 82.5%, натуральный сок ягод, сахар, свежие отборные яйца.', 330, 72, 120, TRUE, TRUE, TRUE, 2, 'KG', 0.5, 0.5, FALSE, NOW(), NOW()),
(103, 1, 'Klassik Qat-qat Napoleon', 'Классический слоёный Наполеон', 'klassik-napoleon', 'Yuzlab ingichka qatlamli xamir va erib ketuvchi nozik vanilli zavarnoy krem uyg''unligi. Asl qadimiy retsept bo''yicha tayyorlangan.', 'Хрустящие тончайшие коржи из слоёного теста на сливочном масле, пропитанные нежным заварным ванильным кремом Патисьер.', 120000, 140000, '2026-11-08T11:38:44.859Z', '1.0 kg', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 'Oliy navli un, 82.5% tabiiy sariyog'', sut, tuxum sarig''i, tabiiy Madagaskar vanili, shakar.', 'Мука пшеничная в/с, сливочное масло 82.5%, цельное фермерское молоко, желтки, натуральная мадагаскарская ваниль, сахар.', 390, 48, 0, TRUE, TRUE, FALSE, 3, 'KG', 0.5, 0.5, FALSE, NOW(), NOW()),
(104, 1, 'Shokoladli Snikers Torti', 'Шоколадный торт «Сникерс»', 'shokoladli-snikers', 'Qovurilgan yeryong''oq, qaymoqli karamel, qalin shokoladli nuga va Belgiya shokoladli ganashi bilan tayyorlangan to''yimli tort.', 'Влажный шоколадный бисквит, солёная домашняя карамель, отборный обжаренный арахис, воздушная нуга и толстый слой шоколадного ганаша.', 160000, 180000, '2026-11-08T08:52:04.859Z', '1.2 kg', 'https://images.unsplash.com/photo-1606890737304-57a1ca8a5b62?w=800&auto=format&fit=crop&q=80', 'Shokolad biskviti, qovurilgan yer yong''og''i, qaynatilgan quyultirilgan sut, qora shokolad, sof sariyog''.', 'Шоколадный бисквит, обжаренный арахис, варёная сгущенка с натуральным маслом, бельгийский темный шоколад, карамель.', 420, 72, 0, TRUE, TRUE, FALSE, 4, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(105, 1, 'Mayin Asalli Medovik', 'Традиционный медовик со сметанным кремом', 'mayin-asalli-medovik', 'Tog'' asali bilan qorilgan 8 ta yupqa xushbo''y qatlam va quyuq tabiiy smetana kremi. Og''izda erib ketuvchi an''anaviy lazzat.', 'Восемь тончайших коржей на натуральном горном мёде с прослойками лёгкого сметанного крема из отборных фермерских сливок.', 125000, NULL, NULL, '1.1 kg', 'https://images.unsplash.com/photo-1588195538326-c5b1e9f80a1b?w=800&auto=format&fit=crop&q=80', 'Tog'' asali, oliy navli un, sariyog'', tabiiy smetana, shakar, tuxum.', 'Натуральный горный мёд, мука высшего сорта, сливочное масло, фермерская сметана, сахар, свежие яйца.', 340, 72, 0, TRUE, FALSE, TRUE, 5, 'KG', 0.5, 0.5, FALSE, NOW(), NOW()),
(106, 1, 'San-Sebastian Kuydirilgan Chizkeyk', 'Испанский чизкейк Сан-Себастьян', 'san-sebastian-chizkeyk', 'Ispancha uslubda yuqori haroratda pishirilgan chizkeyk. Ustki qismi karamellashgan, ichi esa suyuq eruvchan pishloq kremi bilan boyitilgan.', 'Знаменитый баскский чизкейк с карамельной обожжённой корочкой и невероятно нежной, шелковистой тающей сердцевиной.', 155000, 175000, '2026-11-08T14:58:44.859Z', '1.1 kg', 'https://images.unsplash.com/photo-1535141192574-5d4897c13136?w=800&auto=format&fit=crop&q=80', 'Philadelphia krem-pishlog''i, 33% tabiiy qaymoq, tuxum, shakar, makkajo''xori kraxmali, vanil.', 'Сливочный сыр Филадельфия, свежие сливки 33%, яйца, сахар, кукурузный крахмал, натуральная ваниль.', 380, 72, 60, TRUE, TRUE, FALSE, 6, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(201, 2, 'Bento Tort «Love & Berry»', 'Бенто-торт «Love & Berry»', 'bento-love-berry', '1-2 kishi uchun mo''ljallangan yoqimli bento-tort. Vanilli biskvit, rezavor mevali qiyom va romantik tabrik yozuvi bilan.', 'Миниатюрный тортик на 1–2 персоны. Ванильный бисквит, клубнично-малиновый конфитюр, крем-чиз и трогательная романтическая надпись.', 65000, NULL, NULL, '400 g', 'https://images.unsplash.com/photo-1588195538326-c5b1e9f80a1b?w=800&auto=format&fit=crop&q=80', 'Vanilli biskvit, qaymoqli krem-chiz, qulupnay qiyomi, ekologik qamish qutisi va yog''och qoshiq.', 'Ванильный бисквит, сливочный крем-чиз, ягодный конфитюр, натуральные красители. Подается в эко-боксе с деревянной ложечкой.', 280, 72, 30, TRUE, TRUE, TRUE, 7, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(202, 2, 'Bento Tort «Happy Birthday»', 'Бенто-торт «Happy Birthday»', 'bento-happy-birthday', 'Tug''ilgan kun uchun eng ajoyib syurpriz! Mini shamcha va yoqimli tabrik bilan maxsus qutida yetkaziladi.', 'Идеальный сладкий подарок на день рождения: шоколадный бисквит, сливочный мусс, карамель. В комплекте праздничная свеча и ложечка.', 70000, 80000, '2026-11-08T06:05:24.859Z', '450 g', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800&auto=format&fit=crop&q=80', 'Shokoladli biskvit, Maskarpone kremi, karamel va yong''oq bo''laklari.', 'Шоколадный бисквит, крем маскарпоне, домашняя карамель, шоколадный декор, свечка.', 295, 72, 30, TRUE, TRUE, FALSE, 8, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(203, 2, 'Bento Tort «Bismillah & Baraka»', 'Бенто-торт «Бисмиллах и Благодать»', 'bento-bismillah', 'Oila davrasida choy ichish yoki shukrona uchun mo''ljallangan nozik pista va vanil kremli bento-tort.', 'Изысканный бенто-торт с фисташковым кремом и нежным ванильным бисквитом. Прекрасный подарок для семейного благословения.', 68000, NULL, NULL, '420 g', 'https://images.unsplash.com/photo-1565958011703-44f9829ba187?w=800&auto=format&fit=crop&q=80', 'Eron pistasi pastasi, vanilli biskvit, 33% qaymoq, oq shokolad.', 'Фисташковая паста, ванильный бисквит, свежие сливки 33%, бельгийский белый шоколад.', 290, 72, 30, TRUE, FALSE, TRUE, 9, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(204, 2, 'Bolalar Bento Torti «Ayiqcha»', 'Детский бенто-торт «Мишка Тедди»', 'bento-ayiqcha', 'Kichkintoylar uchun xavfsiz va 100% tabiiy bananli biskvit va Maskarpone pishloqli yoqimli ayiqcha surati.', 'Милый детский тортик с натуральным банановым бисквитом, кремом из сыра маскарпоне и шоколадной мордочкой мишки.', 72000, NULL, NULL, '450 g', 'https://images.unsplash.com/photo-1621303837174-89787a7d4729?w=800&auto=format&fit=crop&q=80', 'Banan pyuresi, sut, un, tuxum, maskarpone, tabiiy kakao.', 'Банановое пюре, фермерское молоко, мука высшего сорта, яйца, маскарпоне, какао.', 260, 48, 30, TRUE, TRUE, TRUE, 10, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(301, 3, 'Eron Pistali va Malinali Rulet', 'Фисташковый рулет со спелой малиной', 'pistali-rulet', 'Haqiqiy Eron pistasidan tayyorlangan xushbo''y pasta, yangi nordon malina konfisi va yengil biskvit uyg''unligi.', 'Шедевр кондитерского дома: нежный бисквит с натуральной фисташковой пастой, кислинка спелой малины и лёгкий сливочный крем.', 95000, 110000, '2026-11-08T06:58:44.859Z', '700 g', 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=800&auto=format&fit=crop&q=80', 'Pista pastasi, malina mevalari, qaymoq, oliy navli un, tuxum, shakar kukuni.', 'Натуральная паста из иранских фисташек, ягоды малины, свежие сливки, мука в/с, яйца, сахарная пудра.', 310, 48, 0, TRUE, TRUE, FALSE, 11, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(302, 3, 'Meringali Qulupnayli Rulet', 'Меренговый рулет со свежей клубникой', 'meringali-rulet', 'Og''izda erib ketuvchi qarsildoq merenga qobig''i, yengil qaymoqli krem va yangi qulupnay bo''laklari.', 'Воздушная хрустящая меренга, невесомый крем из сыра маскарпоне и спелые сочные ягоды клубники. Тает во рту!', 110000, NULL, NULL, '650 g', 'https://images.unsplash.com/photo-1541781774459-bb2af2f05b55?w=800&auto=format&fit=crop&q=80', 'Tuxum oqi, shakar, tabiiy 33% qaymoq, maskarpone, barra qulupnay mevalari.', 'Белки отборных яиц, сахарная пудра, сливки 33%, сыр маскарпоне, отборная свежая клубника.', 270, 36, 0, TRUE, TRUE, TRUE, 12, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(303, 3, 'Shokoladli Tryufel Ruleti', 'Шоколадный трюфельный рулет', 'shokoladli-tryufel-rulet', 'Qalin Belgiya qora shokoladli ganashi, nam biskvit va mayda findiq bo''laklari bilan bezatilgan boy rulet.', 'Насыщенный шоколадный бисквит, трюфельный крем на темном бельгийском шоколаде и дроблёный обжаренный фундук.', 88000, NULL, NULL, '650 g', 'https://images.unsplash.com/photo-1571115177098-24ec42ed204d?w=800&auto=format&fit=crop&q=80', 'Qora shokolad 70%, kakao, un, sariyog'', qaymoq, findiq.', 'Темный бельгийский шоколад 70%, какао премиум, мука, сливочное масло, сливки, обжаренный фундук.', 360, 72, 0, TRUE, FALSE, FALSE, 13, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(304, 3, 'Asl Italyancha Tiramisu', 'Классический итальянский Тирамису', 'asl-tiramisu', 'Italyancha Savoyardi pechenyelari, yangi damlangan Arabika espressosi, nozik Maskarpone kremi va kakao sepmalari.', 'Традиционный десерт: печенье савоярди, пропитанное свежесваренным эспрессо с тонким слоем воздушного крема маскарпоне.', 85000, 95000, '2026-11-08T13:02:04.859Z', '500 g', 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?w=800&auto=format&fit=crop&q=80', 'Savoyardi pechenyesi, Arabika qahvasi, Maskarpone pishlog''i, tuxum sarig''i, tabiiy kakao.', 'Печенье савоярди, натуральный кофе арабика, сыр маскарпоне, желтки отборных яиц, натуральный какао-порошок.', 295, 48, 0, TRUE, TRUE, TRUE, 14, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(401, 4, 'Fransuzcha Eklerlar to‘plami (4 dona)', 'Набор французских эклеров (4 шт)', 'fransuzcha-eklerlar', 'Yengil pishgan xushbo''y zavarnoy xamir, ichi to''la vanilli, shokoladli, karamelli va pistali nozik kremlar bilan to''ldirilgan.', 'Четыре изысканных эклера: ванильный с мадагаскарской ванилью, бельгийский шоколад, соленая карамель и фисташковый крем.', 48000, 55000, '2026-11-08T14:25:24.859Z', '4 dona (240 g)', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 'Zavarnoy xamir, tabiiy sut, 82.5% sariyog'', vanil ekstrakti, shokoladli sirlama.', 'Заварное тесто, цельное молоко, натуральное сливочное масло, экстракт ванили, гляссаж из бельгийского шоколада.', 275, 48, 0, TRUE, TRUE, FALSE, 15, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(402, 4, 'Sablé Mevali Tartaletkalari (3 dona)', 'Тарталетки со свежими ягодами (3 шт)', 'mevali-tartaletka', 'Qarsildoq qum xamirli savatcha, ichida mayin vanilli pishloq kremi va ustida yangi uzilgan rezavor mevalar (malina, qulupnay, chernika).', 'Хрустящая миндально-песочная основа сабле, нежный крем дипломат и россыпь свежих ягод малины, клубники и голубики.', 45000, NULL, NULL, '3 dona (270 g)', 'https://images.unsplash.com/photo-1519869325930-281384150729?w=800&auto=format&fit=crop&q=80', 'Bodom uni, sariyog'', shakar, vanil kremi, barra malina, qulupnay, chernika.', 'Миндальная мука, сливочное масло, сахар, ванильный крем дипломат, свежие ягоды малины, клубники, голубики.', 260, 36, 0, TRUE, TRUE, TRUE, 16, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(403, 4, 'Nyu-York Klassik Chizkeyk Pirojniysi', 'Кусочек чизкейка «Нью-Йорк»', 'chizkeyk-nyu-york', 'Og''izda eruvchi haqiqiy Philadelphia pishlog''i va qum xamiri asosi. Choy va qahva bilan ajoyib uyg''unlik.', 'Порционный классический чизкейк Нью-Йорк с плотной кремовой текстурой на песочной основе со сливочным ароматом.', 35000, NULL, NULL, '180 g', 'https://images.unsplash.com/photo-1524351199678-941a58a3df50?w=800&auto=format&fit=crop&q=80', 'Krem-pishloq, tabiiy qaymoq, tuxum, vanil, pechenye.', 'Натуральный сливочный сыр, сливки, свежие яйца, ваниль, хрустящее песочное печенье.', 320, 72, 0, TRUE, FALSE, FALSE, 17, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(404, 4, 'Bolalikning «Kartoshka» Pirojniysi (4 dona)', 'Пирожное «Картошка» премиум (4 шт)', 'kartoshka-pirojnoye', 'Qadrdon bolalik lazzati: boy shokolad biskviti uvog''i, sof sariyog'', quyultirilgan sut va yong''oq bo''laklari.', 'Любимый вкус детства в премиальном исполнении: бисквитная крошка, натуральное сливочное масло, сгущенное молоко и какао.', 32000, NULL, NULL, '4 dona (260 g)', 'https://images.unsplash.com/photo-1558326567-98ae2405596b?w=800&auto=format&fit=crop&q=80', 'Biskvit, sof sariyog'', quyultirilgan sut, kakao, vanil.', 'Шоколадный бисквит, сливочное масло 82.5%, сгущенное молоко, какао, ваниль.', 340, 120, 0, TRUE, FALSE, FALSE, 18, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(501, 5, 'Fransuzcha Sariyog''li Kruassan', 'Французский классический круассан', 'fransuz-kruassani', 'Har tong soat 06:00 da Yevropa pechlarida yangi pishiriladigan qat-qat, havodor va qarsildoq haqiqiy kruassan.', 'Традиционный круассан на натуральном сливочном масле 82.5%. Хрустящая корочка, пышная слоистая текстура и волшебный аромат.', 18000, NULL, NULL, '90 g', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=800&auto=format&fit=crop&q=80', 'Oliy navli un, 82.5% tabiiy sariyog'', sut, xamirturush, shakar, dengiz tuzi.', 'Мука пшеничная в/с, сливочное масло 82.5%, молоко, закваска, сахар, морская соль.', 290, 24, 0, TRUE, TRUE, FALSE, 19, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(502, 5, 'Belgiya Shokoladli Kruassan (Pain au Chocolat)', 'Круассан с бельгийским шоколадом', 'shokoladli-kruassan', 'Ichida ikki chiziq iliq eruvchi Belgiya qora shokoladi bo''lgan hashamatli fransuz nonushta pishirig''i.', 'Знаменитый французский Pain au Chocolat: хрустящее слоёное тесто и две полоски тёмного бельгийского шоколада внутри.', 22000, NULL, NULL, '110 g', 'https://images.unsplash.com/photo-1530610476181-d83430b64dcd?w=800&auto=format&fit=crop&q=80', 'Qatlama xamir, sof sariyog'', Belgiya qora shokoladi 55%, sut.', 'Слоёное тесто, сливочное масло 82.5%, темный бельгийский шоколад 55%, молоко.', 340, 24, 0, TRUE, TRUE, TRUE, 20, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(503, 5, 'Bodomli Kruassan (Amandine)', 'Миндальный круассан Амандин', 'bodomli-kruassan', 'Ichida mayin bodom kremi (franjipan) va ustida qovurilgan yupqa bodom parraklari bilan bezatilgan to''yimli kruassan.', 'Изысканный круассан с нежной миндальной начинкой франжипан, посыпанный лепестками обжаренного миндаля и сахарной пудрой.', 26000, NULL, NULL, '140 g', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 'Qatlama xamir, maydalangan bodom kremi, sof sariyog'', shakar kukuni, bodom barglari.', 'Слоёное тесто, крем из калифорнийского миндаля, сливочное масло, лепестки миндаля, пудра.', 380, 24, 0, TRUE, TRUE, FALSE, 21, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(504, 5, 'Daniya Pishirig''i (Danish) Nordon Olchali', 'Датская слойка с вишней (Даниш)', 'olchali-danish', 'Yengil qatlama xamir markazida quyuq nordon olcha konfyuturi va vanilli krem qatlami.', 'Воздушная хрустящая датская слойка с начинкой из сочной спелой вишни и нежного заварного ванильного крема.', 20000, NULL, NULL, '120 g', 'https://images.unsplash.com/photo-1621303837174-89787a7d4729?w=800&auto=format&fit=crop&q=80', 'Qatlama xamir, olcha mevalari, vanilli krem, shakar sirlamasi.', 'Слоёное тесто на сливочном масле, ягоды вишни, ванильный крем, сахарная глазурь.', 270, 24, 0, TRUE, FALSE, TRUE, 22, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(505, 5, 'Issiq Cinnabon Dolchinli Pishirig''i', 'Булочка Синнабон с корицей и крем-чизом', 'issiq-cinnabon', 'Xushbo''y Indoneziya dolchini bilan o''ralgan yumshoq xamir va ustida erib ketuvchi sariyog''li krem-chiz qatlami.', 'Нежнейшая тёплая булочка с ароматной индонезийской корицей, щедро покрытая тающей глазурью из сливочного сыра.', 24000, 28000, '2026-11-08T10:15:24.859Z', '160 g', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 'Yumshoq xamirturushli xamir, dolchin, sariyog'', krem-chiz, vanil shakar.', 'Дрожжевое сдобное тесто, корица высшего сорта, сливочное масло, крем-чиз, ванильный сахар.', 390, 36, 0, TRUE, TRUE, FALSE, 23, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(601, 6, 'Fransuzcha Makaronlar assortisi (6 dona)', 'Французские макаронс ассорти (6 шт)', 'fransuzcha-makaronlar-6', '100% Kaliforniya bodom unidan tayyorlangan nafis fransuz deserti. 6 xil ta''m: pista, malina, shokolad, karamel, lavanda, mango.', 'Набор из 6 изысканных макаронс на миндальной муке с натуральными ганашами: фисташка, малина, шоколад, карамель, лаванда, манго.', 60000, NULL, NULL, '6 dona (150 g)', 'https://images.unsplash.com/photo-1569864321398-34823a9d9e4a?w=800&auto=format&fit=crop&q=80', '100% maydalangan bodom uni, shakar kukuni, tuxum oqi, tabiiy meva pyurelari, oq va qora shokolad.', 'Миндальная мука высшего сорта, сахарная пудра, белки, пюре натуральных ягод и фруктов, бельгийский шоколад.', 320, 120, 0, TRUE, TRUE, TRUE, 24, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(602, 6, 'Hashamatli Sovg''abop Makaronlar (12 dona)', 'Подарочный набор макаронс Premium (12 шт)', 'fransuzcha-makaronlar-12', 'Zarhal hoshiyali maxsus sovg''a qutisidagi 12 dona turfa rangli nafis makaronlar. Bayramlar va sovg''a uchun mukammal tanlov.', 'Премиальная подарочная золотая коробочка с 12 изысканными макаронс ручной работы. Идеально для признания и праздника.', 115000, 130000, '2026-11-08T17:12:04.859Z', '12 dona (300 g)', 'https://images.unsplash.com/photo-1570476922354-81227cdbb76c?w=800&auto=format&fit=crop&q=80', 'Bodom uni, tuxum oqi, meva va shokolad ganashlari, atlas lenta.', 'Миндальная мука, белок, фруктово-ягодные и шоколадные ганаши, подарочная коробка с лентой.', 320, 120, 0, TRUE, TRUE, FALSE, 25, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(603, 6, 'Qo''lda yasalgan Belgiya Tryufellari qutisi', 'Коробка трюфелей ручной работы', 'shokoladli-tryufel-quti', 'Belgiya shokoladidan tayyorlangan 8 dona elita tryufellari: findiq praline, espresso, apelsin qobig''i va achchiq kakao.', '8 эксклюзивных трюфелей ручной работы из бельгийского шоколада с фундучным пралине, нотками апельсина и эспрессо.', 85000, NULL, NULL, '8 dona (220 g)', 'https://images.unsplash.com/photo-1549007994-cb92caebd54b?w=800&auto=format&fit=crop&q=80', 'Qora va sutli Belgiya shokoladi, 35% qaymoq, findiq, kakao kukuni.', 'Темный и молочный бельгийский шоколад, натуральные сливки 35%, орех фундук, отборное какао.', 440, 180, 0, TRUE, FALSE, TRUE, 26, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(604, 6, 'Parijcha Mevali Marshmallow', 'Натуральный французский маршмеллоу', 'parijcha-marshmou', 'Haqiqiy qulupnay va shaftoli sharbatidan tayyorlangan bulutdek yumshoq, shakar darajasi me''yoridagi marshmallowlar.', 'Воздушные, невесомые кусочки маршмеллоу на натуральном соке клубники и персика без искусственных добавок.', 28000, NULL, NULL, '180 g', 'https://images.unsplash.com/photo-1582293041079-7814c2f12063?w=800&auto=format&fit=crop&q=80', 'Tabiiy meva sharbati, jelatin, shakar, kraxmal, limon kislotasi.', 'Натуральный фруктовый сок, пищевой желатин, сахарная пудра, кукурузный крахмал.', 220, 90, 0, TRUE, FALSE, FALSE, 27, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(701, 7, 'Mualliflik Qulupnayli Raf Qahvasi', 'Авторский клубничный Раф', 'qulupnayli-raf', 'Yangi damlangan espresso, ko''pirtirilgan 10% li qaymoq va tabiiy qulupnayli vanil siropi uyg''unligi.', 'Нежнейший кофейный напиток: свежесваренный эспрессо, взбитый со сливками 10% и натуральным клубнично-ванильным сиропом.', 28000, NULL, NULL, '350 ml', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=800&auto=format&fit=crop&q=80', '100% Arabika espressosi, tabiiy qaymoq, tabiiy qulupnay siropi, vanil.', '100% арабика, пастеризованные сливки, натуральный домашний клубничный сироп, ваниль.', 190, 4, 10, TRUE, TRUE, TRUE, 28, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(702, 7, 'Ispancha Karamel Makkiato', 'Карамельный Маккиато со сливками', 'karamel-makkiato', 'Qalin sut ko''pigi, vanil sirlamasi, yangi espresso va ustida qo''lda qaynatilgan iliq tuzli karamel.', 'Идеальный баланс: густая молочная пенка, насыщенный эспрессо и золотистая домашняя солёная карамель.', 26000, NULL, NULL, '350 ml', 'https://images.unsplash.com/photo-1541167760496-1628856ab772?w=800&auto=format&fit=crop&q=80', 'Espresso, yangi sut, qaymoq, tuzli karamel sousi.', 'Эспрессо арабика, молоко 3.2%, натуральная карамель с морской солью.', 210, 4, 10, TRUE, TRUE, FALSE, 29, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(703, 7, 'Qarshi Tog'' Choyi (Malina va Yalpiz)', 'Чай горный с малиной и мятой (чайник)', 'malina-yalpiz-choy', 'Choynakda damlanuvchi xushbo''y tog'' giyohlari, yangi ezilgan malina, limon va tabiiy tog'' asali.', 'Согревающий авторский чай: горные травы, свежая перетёртая малина, сочный лимон, мята и ложечка натурального мёда.', 25000, NULL, NULL, '600 ml choynak', 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 'Qora va ko''k tog'' choyi, malina, yangi yalpiz, limon, asal.', 'Сбор горных трав, свежая малина, перечная мята, лимон, натуральный мёд.', 70, 6, 10, TRUE, FALSE, TRUE, 30, 'PIECE', 1, 1, FALSE, NOW(), NOW()),
(704, 7, 'Yaponcha Yashil Matcha Latte', 'Японский зелёный Матча Латте', 'muzday-matya-latte', 'Kioto shahridan keltirilgan sifatli yashil choy kukuni, ko''pirtirilgan bodom suti va nozik vanil.', 'Тонизирующий напиток на церемониальном японском чае матча с нежной пенкой растительного миндального молока.', 30000, NULL, NULL, '400 ml', 'https://images.unsplash.com/photo-1536256263959-770b48d82b0a?w=800&auto=format&fit=crop&q=80', 'Yapon matcha choyi, bodom suti, vanil ekstrakti.', 'Церемониальный зеленый чай матча, миндальное молоко, ваниль.', 140, 4, 10, TRUE, FALSE, TRUE, 31, 'PIECE', 1, 1, FALSE, NOW(), NOW())
